    pseudo state Decision;

    state State_1_1 {
        enter {
            EMS_state = 11;
            Pgr = 0.0;
            Pd1r = 0.0;
            Pd2r = 0.0;
            Pbr = 0.0;
            Pbc = Ppv + Pw - PL;
            Ps = 0.0;
            cmd_LNG = 0;
            cmd_DG1 = 0;
            cmd_DG2 = 0;
            cmd_battery_discharge = 0;
            cmd_battery_charge = 1;
            illegal_overload = 0;
        }
    }

    state State_1_2 {
        enter {
            EMS_state = 12;
            Pgr = 0.0;
            Pd1r = 0.0;
            Pd2r = 0.0;
            Pbr = 0.0;
            Pbc = 0.0;
            Ps = Ppv + Pw - PL;
            cmd_LNG = 0;
            cmd_DG1 = 0;
            cmd_DG2 = 0;
            cmd_battery_discharge = 0;
            cmd_battery_charge = 0;
