/bin/bash -lc "PYTHONPATH=project_1_llm_state_machine_modeling python - <<'PY'
from method.schema import StageContext, TestScenario, ScenarioStep, GroundingMap, GroundedElement
from method.stages.api import run_sd2_parse, run_sd3_semantic, run_sd4_design, run_sd6_sim, freeze_scenario_set, run_sd5a_scenario_coverage
import hashlib
nl='''The LNG-ship EMS manages a ship energy system with PVs, WECs, DGs, LNG, batteries, and time-varying ship loads, issuing cut-in and cut-out commands for generating units and loads. It controls power dispatch between generating units and load demand during changing time periods and operating conditions, dynamically switching states to maintain power balance as resources and demands vary. The FSM reads load demand PL, renewable contributions Ppv and Pw, battery state of charge SoC, and engine capacity bounds such as eng3_Pmax, then returns requested generator power, battery discharge or charging power, and spare power. The twelve finite states are selected by logical transition conditions over demand, generation, capacity, and SoC. When Ppv + Pw covers PL, the EMS serves all ship demand from RES and charges batteries while SoC is below 0.95, or treats residual renewable power as spare once SoC is at least 0.95. When Ppv + Pw is below PL, dispatch follows the stated priority: RES first, batteries when SoC is suitable, LNG before diesel units, and DG1/DG2 only as the last priority. Low-SoC branches add explicit charging margins, including Pgmax/5 in an LNG-covered case and Pd1max/10 in later diesel-generator cases. When PL = 0, RES production is sent to battery charging or to spare power according to SoC thresholds. The overload completion state is illegal: if extreme demand exceeds all RES and thermal resources, EMS activates all thermal generating units, covers the lack by battery discharge, and the state shall never occur in practice.'''
dsl=r'''def float PL = 0.0;
def float Ppv = 0.0;
def float Pw = 0.0;
def float SoC = 0.0;
def float eng1_Pmax = 0.0;
def float eng2_Pmax = 0.0;
def float eng3_Pmax = 0.0;
def float Pd1r = 0.0;
def float Pd2r = 0.0;
def float Pgr = 0.0;
def float Pbr = 0.0;
def float Pbc = 0.0;
def float Ps = 0.0;
def int EMS_state = 0;
def int cmd_LNG = 0;
def int cmd_DG1 = 0;
def int cmd_DG2 = 0;
def int cmd_battery_discharge = 0;
def int cmd_battery_charge = 0;
def int illegal_overload = 0;

state LNGShipEMS {
    [*] -> State_3_1;

    state State_1_1 {
        enter {
            EMS_state = 11;
            Pgr = 0.0;
            Pd1r = 0.0;
            Pd2r = 0.0;
            Pbr = 0.0;
            Pbc = Ppv + Pw - PL;
            Ps = 0.0;
            cmd_LNG = 0;
            cmd_DG1 = 0;
            cmd_DG2 = 0;
            cmd_battery_discharge = 0;
            cmd_battery_charge = 1;
            illegal_overload = 0;
        }
    }

    state State_1_2 {
        enter {
            EMS_state = 12;
            Pgr = 0.0;
            Pd1r = 0.0;
            Pd2r = 0.0;
            Pbr = 0.0;
            Pbc = 0.0;
            Ps = Ppv + Pw - PL;
            cmd_LNG = 0;
            cmd_DG1 = 0;
            cmd_DG2 = 0;
            cmd_battery_discharge = 0;
            cmd_battery_charge = 0;
            illegal_overload = 0;
        }
    }

    state State_2_1 {
        enter {
            EMS_state = 21;
            Pgr = 0.0;
            Pd1r = 0.0;
            Pd2r = 0.0;
            Pbr = PL - Ppv - Pw;
            Pbc = 0.0;
            Ps = 0.0;
            cmd_LNG = 0;
            cmd_DG1 = 0;
            cmd_DG2 = 0;
            cmd_battery_discharge = 1;
            cmd_battery_charge = 0;
            illegal_overload = 0;
        }
    }

    state State_2_2 {
        enter {
            EMS_state = 22;
            Pgr = PL - Ppv - Pw + eng3_Pmax / 5.0;
            Pd1r = 0.0;
            Pd2r = 0.0;
            Pbr = 0.0;
            Pbc = eng3_Pmax / 5.0;
            Ps = 0.0;
            cmd_LNG = 1;
            cmd_DG1 = 0;
            cmd_DG2 = 0;
            cmd_battery_discharge = 0;
            cmd_battery_charge = 1;
            illegal_overload = 0;
        }
    }

    state State_2_3 {
        enter {
            EMS_state = 23;
            Pgr = eng3_Pmax;
            Pd1r = 0.0;
            Pd2r = 0.0;
            Pbr = PL - Ppv - Pw - eng3_Pmax;
            Pbc = 0.0;
            Ps = 0.0;
            cmd_LNG = 1;
            cmd_DG1 = 0;
            cmd_DG2 = 0;
            cmd_battery_discharge = 1;
            cmd_battery_charge = 0;
            illegal_overload = 0;
        }
    }

    state State_2_4 {
        enter {
            EMS_state = 24;
            Pgr = eng3_Pmax;
            Pd1r = PL - Ppv - Pw - eng3_Pmax + eng1_Pmax / 10.0;
            Pd2r = 0.0;
            Pbr = 0.0;
            Pbc = eng1_Pmax / 10.0;
            Ps = 0.0;
            cmd_LNG = 1;
            cmd_DG1 = 1;
            cmd_DG2 = 0;
            cmd_battery_discharge = 0;
            cmd_battery_charge = 1;
            illegal_overload = 0;
        }
    }

    state State_2_5 {
        enter {
            EMS_state = 25;
            Pgr = eng3_Pmax;
            Pd1r = eng1_Pmax;
            Pd2r = 0.0;
            Pbr = PL - Ppv - Pw - eng3_Pmax - eng1_Pmax;
            Pbc = 0.0;
            Ps = 0.0;
            cmd_LNG = 1;
            cmd_DG1 = 1;
            cmd_DG2 = 0;
